import {C,Q} from './course-types';
export const programmingEntries=[
C({id:'8.1.1',title:'Named boxes: variables and constants',minutes:11,opening:'A game needs to remember a changing score and a fixed maximum. Give each value a clear name.',mission:'Declare values, then watch assignment change a variable.',sections:[['Declare a variable before using it','A variable is a named storage location whose value can change during a program. A declaration introduces its name and data type, the kind of value it can hold. DECLARE Score : INTEGER declares a variable for whole-number scores. A meaningful name explains its purpose.','A declaration introduces a variable’s name and data type.'],['Assignment stores a new value','Score ← 4 stores 4 in Score. Score ← Score + 1 reads the old value, adds one, then replaces it with the new value. The arrow means assignment, not a permanent equality. After the second instruction, Score holds 5.','Assignment replaces the variable’s stored value using the expression’s result.'],['Keep a fixed value as a constant','A constant is a named value not changed during the run. CONSTANT MaxScore = 100 defines a fixed maximum. Use the constant in calculations or comparisons instead of repeating an unexplained number. Its declaration differs from a variable’s because its value is fixed.','A constant keeps a fixed named value during execution.']],worked:['Declare a score, set it to 7, then increase it by 2.',['Declare','Score is declared as an integer before being used.',[['Declaration','DECLARE Score : INTEGER'],['Purpose','Whole-number score']]],['Assign','Store the starting score 7.',[['Statement','Score ← 7'],['Stored value','7']]],['Update','Read 7, add 2 and store 9 back in Score.',[['Statement','Score ← Score + 2'],['New value','9']]]],practice:[Q('Score is 6. After Score ← Score + 3, what does it hold?','9',['9','3','6'],'The right side is evaluated using the old value, then assigned back.',[['Old Score','6'],['Expression','6 + 3'],['New Score','9']]),Q('A maximum of 100 must stay unchanged during the run. Which declaration concept suits it?','Constant',['Constant','Changing variable'],'A constant names a fixed value.',[['Requirement','Fixed maximum'],['Value','100'],['Concept','Constant']])],assessment:[Q('What is a variable?','A named storage location whose value can change',['A named storage location whose value can change','A fixed physical printer','A URL only'],'Variables hold changing program values.'),Q('What does DECLARE Count : INTEGER introduce?','An integer variable named Count',['An integer variable named Count','A floating-point image','An output command'],'The declaration specifies name and type.'),Q('Which statement correctly describes assignment?','Evaluate the expression, then store its result in the named variable',['Evaluate the expression, then store its result in the named variable','Keep both sides as a permanent algebraic equality','Never replace an earlier value'],'Assignment updates stored state.')],mistake:'A declaration and an assignment do different jobs: one introduces a name/type; the other gives it a value.',exam:'Declare and use variables and constants with meaningful identifiers and appropriate values.',simple:'A variable is a labelled box whose contents can be replaced. A constant is a named value the program keeps fixed.',another:'DECLARE Lives : INTEGER, then Lives ← 3. After losing a life, Lives ← Lives − 1 gives 2.',helpFrames:[['Declare','Lives : INTEGER'],['Start','Lives = 3'],['Update','Lives = 2']],terms:['variable','constant','pseudocode']}),
C({id:'8.1.2',title:'Choose the kind of value',minutes:12,opening:'15, 1.5, "A", "HELLO" and TRUE are different kinds of data. Choose a type that matches the job.',mission:'Sort example values into five basic data types.',sections:[['Use integer or real for numbers','An integer holds a whole number, such as −3, 0 or 15. A real holds a numeric value that can have a fractional part, such as 1.5. Choose an integer for a count of people and a real for a measured height. A number stored as quoted text is a string, not a value ready for arithmetic.','Integer stores whole numbers; real can store fractional numeric values.'],['Use char or string for text','Char, or character, holds one character, such as "A". A string holds a sequence of characters, such as "AB12". A string may have one character too, so the declared type and intended use matter; a one-character example alone does not force every language to treat it as char.','Char holds one character; string holds text as a sequence of characters.'],['Use Boolean for a two-value condition','Boolean has the values TRUE and FALSE. HasTicket can be TRUE or FALSE; a test such as Age >= 16 produces a Boolean result. Choose a type by the data’s meaning and the operations needed, rather than only how it looks on screen.','Boolean holds TRUE or FALSE and represents conditions.']],worked:['Choose types for a ticket count, measured distance and admission decision.',['Count whole items','NumberOfTickets is an integer because tickets are counted in whole items.',[['Value','4 tickets'],['Type','INTEGER']]],['Store a measurement','Distance can include a fraction, so use real.',[['Value','1.75 km'],['Type','REAL']]],['Store a condition','MayEnter records a yes/no decision as TRUE or FALSE.',[['Value','TRUE'],['Type','BOOLEAN']]]],practice:[Q('A temperature of 18.6 must retain its fractional part. Which numeric type suits it?','Real',['Real','Integer'],'A real can retain a fractional numeric value.',[['Value','18.6'],['Need','Fractional part'],['Type','Real']]),Q('The value records whether a door is open. Which type suits TRUE/FALSE?','Boolean',['Boolean','Real','Char'],'A Boolean represents the two logical states TRUE and FALSE.',[['Meaning','Is the door open?'],['Possible values','TRUE / FALSE'],['Type','Boolean']])],assessment:[Q('Which type is suitable for the number of students in a class?','Integer',['Integer','Char','Boolean'],'A student count is a whole number.'),Q('Which type suits a person’s full name?','String',['String','Boolean','Integer'],'A name is a sequence of characters.'),Q('Why might a code such as "007" be stored as a string?','Its characters and leading zeros matter rather than arithmetic value',['Its characters and leading zeros matter rather than arithmetic value','It must always be added to another number','Every digit sequence is automatically an integer'],'Identifiers may be textual even when they contain digits.')],mistake:'Digits in quotes can be text. Do not assume a code should be numeric just because it contains digits.',exam:'Use integer, real, char, string and Boolean types appropriately, explaining choices in context.',simple:'Choose a box designed for the value: whole number, fractional number, one character, text or true/false.',another:'A room code "B12" is a string, a house letter can be char, and the number of occupied seats is integer.',helpFrames:[['Room code','STRING: B12'],['House letter','CHAR: B'],['Occupied seats','INTEGER: 12']],terms:['variable','boolean','string']}),
C({id:'8.1.3',title:'Ask for input and show output',minutes:10,opening:'A program can ask your name, remember what you type and display a greeting. Follow the direction of the data.',mission:'Send input into a prepared greeting program.',sections:[['Prompt before asking for a value','Output sends information from a program to a user or another destination. A prompt is output asking for information, such as OUTPUT "Enter your name". A clear prompt tells the user what to enter before the program reads it.','A prompt is output that explains the expected input.'],['Read input into a variable','INPUT Name reads the supplied value into a variable called Name. Declare the variable with a suitable type, such as STRING. Input brings data into the program; it does not automatically prove the data is valid. Apply checks when the requirement needs them.','Input reads supplied data into a suitable variable.'],['Display literal text and stored values','OUTPUT Name displays the value held in Name. OUTPUT "Hello" displays literal text: the characters written between quotes. A greeting can combine fixed text with a variable value. Keep the distinction between a variable’s name and the text stored in it.','Output can display literal text, variable values or calculated results.']],worked:['A program asks for a favourite colour and displays it.',['Prompt','Display a clear instruction to the user.',[['Output','Enter your favourite colour'],['Purpose','Tell user what to supply']]],['Read','Store the entered text, such as blue, in Colour.',[['Input','blue'],['Variable','Colour = "blue"']]],['Output','Display the stored value with a message.',[['Fixed text','Your colour is'],['Stored value','blue']]]],practice:[Q('What direction does INPUT bring data?','Into the program',['Into the program','Only out to a printer'],'Input supplies data for processing.',[['User','Supplies a value'],['Direction','Into program'],['Statement','INPUT']]),Q('Does OUTPUT "Name" display the variable’s value or the quoted word?','The quoted word',['The quoted word','The variable’s value'],'Quoted text is literal text, so it displays Name itself.',[['Statement','OUTPUT "Name"'],['Quotes','Literal text'],['Displayed','Name']])],assessment:[Q('Why display a prompt before reading input?','To explain what the user should enter',['To explain what the user should enter','To guarantee every value is valid','To erase the variable'],'Prompts guide the input action.'),Q('After INPUT Age receives 15, what does OUTPUT Age display?','15',['15','The word Age','Nothing can ever be displayed'],'Without quotes, the variable’s stored value is output.'),Q('Which sequence is suitable for a simple input task?','Declare variable → prompt → input → process/output',['Declare variable → prompt → input → process/output','Output an unknown value → declare it later','Delete input → remove prompt'],'This makes the data and interaction clear.')],mistake:'INPUT and OUTPUT are not interchangeable. A prompt is output even when it is followed by input.',exam:'Declare appropriate variables and use clear input and output statements, distinguishing literal text from stored values.',simple:'The program says what it needs, you supply a value, and the program can use and display that value.',another:'OUTPUT "Enter score" prompts the user. INPUT Score stores 8. OUTPUT Score * 2 displays 16.',helpFrames:[['Prompt','Enter score'],['Input','Score = 8'],['Output','16']],terms:['input','output','variable','string','pseudocode']}),
C({id:'8.1.4',title:'Order, choose, repeat and work with values',minutes:35,opening:'Start with one instruction, then add one new idea at a time: order, choices, repetition, text and calculations.',mission:'Try six programming ideas, one at a time.',recap:['Sequence orders instructions; IF and CASE select a path; FOR, WHILE and REPEAT control repetition.','Totalling adds values, counting adds one, and string routines handle length, substrings and letter case.','Arithmetic calculates values, relational operators compare them, and AND/OR/NOT combine Boolean conditions.'],sections:[['Sequence: do steps in order','Sequence means instructions execute in their written order. Input a value before using it; initialise a total before adding to it. In the first workbench, move through three assignments and watch the stored value after each. Changing the order can change the result.','Instructions execute in sequence unless control flow changes it.'],['Selection: choose a path','Selection chooses instructions using a condition or value. IF Mark >= 50 THEN chooses the pass branch; ELSE handles the other case. CASE compares one value with several stated choices and can include OTHERWISE for unmatched values. A condition such as Mark >= 50 evaluates to TRUE or FALSE.','IF and CASE choose between paths.'],['Iteration: repeat with a rule','Iteration repeats instructions. FOR is count-controlled and repeats over a stated range. WHILE tests its condition before the body, so it can run zero times. REPEAT runs the body before testing UNTIL, so it runs at least once and stops when the condition becomes TRUE. Each loop must update what is needed to make progress.','FOR, WHILE and REPEAT decide repetition differently.'],['Total values, count items','Initialise Total and Count to zero. For each value, Total ← Total + Value adds its magnitude; Count ← Count + 1 records another item. A condition can limit which values count, such as counting only marks >= 50. Do not add the mark itself when the task is to count passes.','Totalling and counting use different updates.'],['Handle strings','LENGTH returns the number of characters. SUBSTRING takes a start position and length to select part of the text. UCASE and LCASE return upper-case and lower-case text. This activity uses one-based character positions: the first character is position 1. Other permitted conventions may start at zero; be consistent with the given algorithm.','String handling includes length, substring, upper case and lower case.'],['Use arithmetic and comparisons','Arithmetic operators are +, −, /, *, ^ for powers, DIV for the integer quotient and MOD for the remainder. For positive integers, 17 DIV 5 is 3 and 17 MOD 5 is 2. Relational operators =, <, <=, >, >= and <> compare values; <> means not equal. AND is true when both conditions are true; OR when at least one is true; NOT reverses a Boolean result. Use parentheses to make intended grouping clear.','Arithmetic, relational and logical operators perform different jobs.']],worked:['Read three marks, total them and count how many are at least 50. Use 40, 60 and 80.',['Initialise and follow the sequence','Start Total at 0 and Passes at 0 before processing marks.',[['Total','0'],['Passes','0']]],['Repeat and select','For each mark add it to Total. Increase Passes by 1 only when Mark >= 50.',[['Marks','40, 60, 80'],['Total','180'],['Passes','2']]],['Output the results','Output Total and Passes. Their meanings differ: 180 is a sum; 2 is an item count.',[['Sum of marks','180'],['Number of passes','2']]]],practice:[Q('Which loop can run zero times because its condition is tested before the body?','WHILE',['WHILE','REPEAT'],'WHILE tests first; REPEAT runs its body before the UNTIL test.',[['Test first','Condition may already be false'],['Body','Can be skipped'],['Loop','WHILE']]),Q('What are 17 DIV 5 and 17 MOD 5?','3 and 2',['3 and 2','2 and 3','3.4 and 0'],'Three whole groups of five use 15, leaving a remainder of 2.',[['Whole groups','3 × 5 = 15'],['Left over','17 − 15 = 2'],['DIV / MOD','3 / 2']]),Q('With one-based positions, SUBSTRING("HELLO", 2, 3) returns what?','ELL',['ELL','HEL','LLO'],'Start at position 2 and take three characters: E, L, L.',[['Positions','H1 E2 L3 L4 O5'],['Take','2 through 4'],['Substring','ELL']])],assessment:[Q('Which loop executes its body before checking whether to stop?','REPEAT…UNTIL',['REPEAT…UNTIL','WHILE','An IF statement'],'A post-condition REPEAT loop runs at least once.'),Q('Which update counts one more qualifying item?','Count ← Count + 1',['Count ← Count + 1','Count ← Count + Value','Count ← 0 every time'],'Counting increments by one per qualifying item.'),Q('What does <> mean in a comparison?','Not equal to',['Not equal to','Always equal to','Raised to a power'],'<> is the not-equal relational operator.'),Q('What is LENGTH("HELLO")?','5',['5','4','1'],'There are five characters.'),Q('What is UCASE("Abc")?','ABC',['ABC','abc','AbcAbc'],'UCASE returns upper-case text.'),Q('When is A AND B true?','When both A and B are true',['When both A and B are true','Whenever either is false','Only when both are false'],'AND requires both conditions to hold.'),Q('When is A OR B true?','When at least one is true',['When at least one is true','Only when both are false','Only when exactly one must be true'],'Inclusive OR allows either or both.'),Q('What is NOT TRUE?','FALSE',['FALSE','TRUE','17'],'NOT reverses a Boolean value.'),Q('What does CASE choose using?','A value compared with stated alternatives',['A value compared with stated alternatives','Only a fixed repeat count','The file size always'],'CASE selects a matching alternative.'),Q('What is 2 ^ 3 in this pseudocode?','8',['8','6','1'],'^ denotes raising to a power.'),Q('What is LCASE("Hi")?','hi',['hi','HI','HiHi'],'LCASE returns lower-case text.'),Q('Why can changing the order of assignments change a result?','Later expressions use the values stored by earlier steps',['Later expressions use the values stored by earlier steps','Sequence never matters','All assignments happen before any inputs'],'Sequence determines which values each step sees.')],mistake:'REPEAT stops when its UNTIL condition becomes true; WHILE continues while its condition is true. Do not swap these meanings.',exam:'Use sequence, IF/CASE, FOR/WHILE/REPEAT, totalling/counting, all four string operations and the listed arithmetic, relational and logical operators.',simple:'Do steps in order, choose a branch when needed and repeat a group using a clear rule. Separately, practise each kind of value operation before combining them.',another:'For 20, 55 and 70, total all marks to get 145 and count two passes using >= 50. The total and count are separate variables.',helpFrames:[['Marks','20, 55, 70'],['Total','145'],['Pass count','2']],terms:['sequence','selection','iteration','variable','string','boolean','pseudocode']}),
C({id:'8.1.5',title:'Put one statement inside another',minutes:13,opening:'A classroom has rows of seats. “For every row, visit every seat” is a loop inside a loop.',mission:'Follow nested loops and nested decisions.',sections:[['Nesting means inside','A nested statement sits inside another statement’s block. An IF inside another IF is nested selection. A loop inside another loop is nested iteration. Indentation makes the boundaries visible, but the actual opening and closing statements determine the structure.','Nesting places selection or iteration inside another statement.'],['Follow each inner loop fully','For each outer-loop value, the inner loop runs through its own values. With 2 rows and 3 columns, the six positions are (1,1), (1,2), (1,3), (2,1), (2,2), (2,3). The inner loop starts again for each new row.','An inner loop completes its sequence for every outer iteration.'],['Follow conditions in order','In nested selection, an inner IF is reached only if its containing branch is taken. Trace the outer condition first. The syllabus requires no more than three nesting levels; this lesson begins with two so each change is visible.','An inner condition is checked only when control reaches its enclosing branch.']],worked:['Visit every position in a 2-row, 2-column grid.',['Start row 1','The outer loop sets Row to 1; the inner loop visits columns 1 and 2.',[['Outer value','Row = 1'],['Inner values','Column = 1, then 2']]],['Start row 2','The outer loop advances; the inner loop begins again at column 1.',[['Outer value','Row = 2'],['Inner values','Column = 1, then 2']]],['Count the visits','Two rows times two columns produces four visits.',[['Positions','(1,1), (1,2), (2,1), (2,2)'],['Total','4']]]],practice:[Q('An outer loop runs 3 times and an inner loop runs 2 times for each. How many inner-body executions occur?','6',['6','5','3'],'The inner body runs twice for each of three outer iterations.',[['Outer repeats','3'],['Inner repeats each time','2'],['Total','3 × 2 = 6']]),Q('If an outer IF branch is not taken, is an IF inside that branch checked?','No',['No','Yes, always'],'Control never reaches the inner statement in that branch.',[['Outer condition','False'],['Containing branch','Skipped'],['Inner condition','Not reached']])],assessment:[Q('What is nested iteration?','A loop inside another loop',['A loop inside another loop','Two unrelated files','Only one assignment'],'One loop controls repeated runs of another.'),Q('In a row/column nested loop, what happens to the inner column loop when a new row starts?','It runs again from its starting value',['It runs again from its starting value','It is permanently deleted','It skips all columns'],'The inner loop restarts for each outer iteration.'),Q('Why is indentation useful in nested code?','It makes which statements belong inside each block easier to see',['It makes which statements belong inside each block easier to see','It changes every condition to true','It removes all closing statements'],'Layout helps people read the structure.')],mistake:'Add the repeated work multiplicatively: 2 rows with 3 visits each gives 6, not 2 + 3.',exam:'Use nested selection and iteration, with no more than three nesting levels.',simple:'For each box, unpack every item inside it before moving to the next box. The inner work repeats for every outer item.',another:'For 3 rows and 2 columns, visit six positions. The column counter returns to 1 whenever the next row starts.',helpFrames:[['Outer loop','3 rows'],['Inner loop','2 columns per row'],['Visits','6 positions']],terms:['iteration','selection','variable','pseudocode']}),
C({id:'8.1.6',title:'Reusable routines and the values they use',minutes:20,opening:'Instead of writing the same instructions repeatedly, give them a name and call them when needed.',mission:'Call procedures and functions, then inspect local and global values.',sections:[['A procedure performs a named task','A procedure is a named group of instructions. Define it once, then CALL it where needed. A procedure can display output or perform another action; it does not return a value as a function result. It may have no parameters or receive named parameter values from the call.','A procedure performs a task when called, with or without parameters.'],['A function returns a value','A function is a named routine returning a value to its caller. A parameter is a named input used within the routine. Area(4,3) supplies 4 and 3 to its length and width parameters and can return 12. Store the result or use it in an expression. The syllabus allows up to three parameters for these routines.','A function returns a result; parameters supply values to a routine.'],['Local and global scope differ','A local variable is declared for use inside its routine. A global variable is available across the relevant program scope. Scope means where a name can be used. Local variables help routines keep their work separate; a global value can be shared but can also be changed from more places. Trace which declaration a name refers to, especially if names repeat.','Local variables belong to a routine’s scope; global variables can be shared more widely.']],worked:['Define a function Area(Length, Width) that returns their product, then call Area(5,4).',['Pass the values','The call supplies 5 for Length and 4 for Width.',[['Call','Area(5,4)'],['Parameters','Length = 5, Width = 4']]],['Work inside the routine','A local Result is assigned Length * Width, giving 20.',[['Local calculation','5 * 4'],['Local Result','20']]],['Return to the caller','RETURN Result sends 20 back. The caller can assign it to FloorArea.',[['Returned value','20'],['Caller variable','FloorArea = 20']]]],practice:[Q('Which kind of routine returns a value to its caller?','Function',['Function','Procedure'],'A function returns a result that can be used by the caller.',[['Routine','Calculates a result'],['Caller','Receives that value'],['Kind','Function']]),Q('A variable declared inside a procedure for its own work is what kind?','Local',['Local','Global in every case'],'Its declaration limits where it is available.',[['Declaration','Inside routine'],['Use','That routine’s scope'],['Kind','Local']])],assessment:[Q('What do parameters provide?','Values a routine uses when it is called',['Values a routine uses when it is called','Only file names for every program','A new CPU core'],'Parameters carry inputs into a routine.'),Q('How does a procedure differ from a function here?','A procedure performs a task without returning a function-result value',['A procedure performs a task without returning a function-result value','A procedure can never display output','A function cannot receive parameters'],'Procedures can act; functions specifically return a value.'),Q('Why can local variables help maintain a program?','They keep a routine’s working values separate from unrelated code',['They keep a routine’s working values separate from unrelated code','They make all values visible everywhere','They remove the need for routine calls'],'Limited scope reduces unintended interference.')],mistake:'Displaying a value inside a procedure is output. Returning a function result to its caller is a different operation.',exam:'Define and use procedures/functions with zero to three parameters; distinguish returned values, calls, local and global scope.',simple:'A named recipe can do a task when called. A function also hands a result back. Local working notes stay inside that recipe; global information is shared.',another:'Volume(2,3,4) receives three dimensions and returns 24. A separate ShowVolume procedure can display it.',helpFrames:[['Parameters','2, 3, 4'],['Function return','24'],['Procedure output','Display 24']],terms:['procedure','function','parameter','variable','pseudocode']}),
C({id:'8.1.7',title:'Use a ready-made routine',minutes:13,opening:'A program does not need a newly written solution for every small calculation. Library routines provide reusable operations.',mission:'Try DIV, MOD, ROUND and RANDOM with clear inputs.',sections:[['Use library operations correctly','A library routine is a supplied reusable operation. Know its inputs, result and limits before using it. For positive integers, DIV returns the whole-number quotient and MOD returns the remainder. 23 DIV 5 is 4; 23 MOD 5 is 3. These are also listed as arithmetic operations in the syllabus.','DIV gives the integer quotient; MOD gives the remainder.'],['Round to a requested number of decimal places','ROUND(Value, Places) rounds a number to the specified decimal places. ROUND(3.146,2) gives 3.15. Rounding changes the stored or returned numeric approximation; displaying extra zeros is a separate formatting matter. Follow the convention in the question for exact halfway cases.','ROUND returns a number rounded to the specified decimal places.'],['Generate a random value','RANDOM() generates a random real value between 0 and 1 inclusive, following the Cambridge pseudocode definition. Repeating it can give different values. Scaling it changes the range. The syllabus example uses ROUND(RANDOM() * 6,0) to obtain a whole number from 0 to 6; it does not promise every rounded result is equally likely.','RANDOM supplies a value used for randomised behaviour; its range matters.']],worked:['Use 23 and 5 with DIV and MOD, then round 3.146 to two places.',['Find whole groups','Four groups of 5 fit into 23.',[['Expression','23 DIV 5'],['Result','4']]],['Find the remainder','23 − 4 × 5 leaves 3.',[['Expression','23 MOD 5'],['Result','3']]],['Round a decimal','Two places keep hundredths; the following digit 6 rounds 3.14 up to 3.15.',[['Expression','ROUND(3.146,2)'],['Result','3.15']]]],practice:[Q('What is 19 MOD 4?','3',['3','4','4.75'],'Four whole groups of 4 use 16 and leave 3.',[['Whole groups','4 × 4 = 16'],['Remainder','19 − 16'],['MOD result','3']]),Q('What does ROUND(2.718,2) return?','2.72',['2.72','2.71','3'],'Round to two decimal places using the next digit.',[['Keep','2.71'],['Next digit','8 rounds up'],['Result','2.72']])],assessment:[Q('What is 19 DIV 4?','4',['4','3','4.75'],'DIV returns the whole-number quotient for these positive integers.'),Q('What does RANDOM() provide in this model?','A real value between 0 and 1 inclusive',['A real value between 0 and 1 inclusive','Always the integer 6','Only TRUE or FALSE'],'The range matters when scaling random values.'),Q('Why check a library routine’s inputs and result?','To use its operation and limits correctly',['To use its operation and limits correctly','Because its name proves any use correct','To avoid needing any test cases'],'A supplied routine still needs correct arguments and expectations.')],mistake:'DIV and MOD are different. Also, rounding a scaled random value does not automatically create equal probabilities for all outcomes.',exam:'Use MOD, DIV, ROUND and RANDOM appropriately, following the routine conventions and required output.',simple:'Use a trusted tool for a known small job, but first check what you put in and what it gives back.',another:'14 DIV 3 is 4 and 14 MOD 3 is 2. ROUND(7.26,1) gives 7.3.',helpFrames:[['Whole groups','14 DIV 3 = 4'],['Remainder','14 MOD 3 = 2'],['Round','7.26 → 7.3']],terms:['function','parameter','pseudocode']}),
C({id:'8.1.8',title:'Make a program easier to maintain',minutes:11,opening:'Code is read again when someone fixes or changes it. Clear names and well-chosen routines make that work easier.',mission:'Improve a prepared program’s readability.',sections:[['Choose meaningful identifiers','An identifier is a name for a variable, constant, array, procedure or function. Names such as TotalCost and CalculateAverage explain purpose more clearly than unrelated letters. Use a consistent style and avoid names that mislead about what a value or routine does.','Meaningful identifiers explain the purpose of values and routines.'],['Comment what needs explaining','Comments are notes in source code ignored during execution. Explain purpose, assumptions or a non-obvious step. Use the language’s comment syntax. Relevant comments help; repeating every obvious instruction in a comment adds clutter and can become misleading if not updated.','Relevant comments explain purpose and assumptions using the language’s comment syntax.'],['Use routines for clear responsibilities','Procedures and functions give repeated or separate tasks meaningful names. A smaller routine with one clear job is easier to understand, test and change. Appropriate structure and formatting make code maintainable, but must preserve its behaviour.','Well-chosen procedures/functions organise reusable work and support maintenance.']],worked:['Improve code that totals marks using unexplained names.',['Rename the values','Replace vague names a and b with Mark and Total.',[['Before','a, b'],['After','Mark, Total']]],['Explain the purpose','A useful comment says that only valid marks are included.',[['Comment','Total valid marks only'],['Purpose','Explain the rule']]],['Separate a task','A CalculateAverage function can name and reuse the average calculation.',[['Routine','CalculateAverage'],['Benefit','Clear reusable calculation']]]],practice:[Q('Which name better explains a variable holding the number of tickets?','TicketCount',['TicketCount','x9'],'TicketCount identifies the value’s purpose.',[['Stored meaning','Number of tickets'],['Clear identifier','TicketCount'],['Benefit','Easier to read']]),Q('Should a comment be updated when the rule it describes changes?','Yes',['Yes','No'],'An outdated comment can mislead a future reader.',[['Rule','Changed'],['Old comment','Now inaccurate'],['Action','Update it']])],assessment:[Q('What is an identifier?','A name for a program element such as a variable or function',['A name for a program element such as a variable or function','Only an IP address','Only a binary digit'],'Identifiers name program elements.'),Q('Which comment is most useful?','One explaining a non-obvious assumption',['One explaining a non-obvious assumption','A false description of old behaviour','An unrelated sentence'],'Relevant comments aid understanding.'),Q('Why place a repeated calculation in a function?','It gives the task a clear reusable definition',['It gives the task a clear reusable definition','It guarantees the algorithm cannot be wrong','It prevents all future changes'],'A routine can centralise and clarify repeated work.')],mistake:'More comments do not automatically mean better code. Use accurate, relevant comments and clear names.',exam:'Use meaningful identifiers for variables/constants/arrays/routines, appropriate comments and procedures/functions to create maintainable programs.',simple:'Leave the next reader clear labels and helpful notes, and group related work into named tasks.',another:'Use MaxAttempts instead of an unexplained 3, and put a repeated input check in a clearly named procedure.',helpFrames:[['Constant name','MaxAttempts'],['Routine name','CheckInput'],['Maintenance','Meaning easier to follow']],terms:['variable','constant','array','procedure','function','sourceCode']}),
C({id:'8.2.1',title:'Store values in a row or grid',minutes:16,opening:'A class has several marks. Instead of giving every mark an unrelated name, store them in an indexed collection.',mission:'Read and change cells in 1D and 2D arrays.',sections:[['Declare a one-dimensional array','An array is an indexed collection of values of the same data type. A 1D array uses one index. DECLARE Marks : ARRAY[1:5] OF INTEGER creates five integer positions numbered 1 to 5. Marks[3] reads the third position; Marks[3] ← 8 writes 8 there.','A 1D array uses one index within declared bounds.'],['Declare a two-dimensional array','A 2D array uses two indexes, often shown as row and column. DECLARE Seats : ARRAY[1:2,1:3] OF STRING creates 2 × 3 positions. Seats[2,1] refers to row 2, column 1 in this model. Use the declared ordering rather than guessing which index comes first.','A 2D array uses two indexes, such as row and column.'],['Use variables as indexes','An index can be a variable: Marks[Index] selects the position currently stored in Index. Check that it stays within the declared bounds. The first index may be zero or one depending on the declaration; these activities use one-based indexes consistently.','Index variables select positions; zero- or one-based bounds must be followed consistently.']],worked:['A 1D array Marks has bounds 1:4 and values 6, 8, 5, 9. Set Index to 2 and replace that mark with 10.',['Read the index','Index is 2, which lies within 1 to 4.',[['Index','2'],['Bounds','1:4']]],['Select the value','Marks[Index] refers to the second value, 8.',[['Expression','Marks[2]'],['Old value','8']]],['Write the new value','Assigning 10 replaces only the selected cell.',[['Statement','Marks[Index] ← 10'],['New array','6, 10, 5, 9']]]],practice:[Q('How many indexes select one cell in a 2D array?','2',['2','1','0'],'A 2D position uses two indexes, such as row and column.',[['Position','Row + column'],['Dimensions','Two'],['Indexes','2']]),Q('For bounds 1:5, is index 0 valid?','No',['No','Yes'],'The declaration permits indexes 1 through 5 only.',[['Declared bounds','1:5'],['Candidate','0'],['Result','Out of bounds']])],assessment:[Q('What do values in one array share in this syllabus model?','The same data type',['The same data type','The same value always','The same screen colour'],'Arrays hold indexed values of one declared type.'),Q('In a row-first grid, what does Grid[2,3] select?','Row 2, column 3',['Row 2, column 3','Row 3, column 2','Every grid cell'],'Follow the declared index convention.'),Q('Why can Marks[Index] select different cells during a loop?','The value of Index changes',['The value of Index changes','The array must be renamed every time','Indexes are never stored in variables'],'A changing index variable selects the current position.')],mistake:'An index identifies a position. It is not necessarily the same as the value stored there.',exam:'Declare and use 1D and 2D arrays, read/write cells, use variable indexes and follow the given zero- or one-based bounds.',simple:'A row of labelled compartments needs one position number. A grid needs a row number and a column number.',another:'In a 2 × 3 grid, Grid[1,3] and Grid[2,3] are different cells in the same column.',helpFrames:[['First cell','Row 1, column 3'],['Second cell','Row 2, column 3'],['Shared feature','Column 3']],terms:['array','variable','string','pseudocode']}),
C({id:'8.2.2',title:'Why use an array?',minutes:10,opening:'A program that handles one mark today may need thirty tomorrow. A collection gives those values a consistent structure.',mission:'Compare separate names with an indexed collection.',sections:[['Group related values','Arrays hold related values under one name, such as Marks. Each position has an index, so the program can select a particular mark without creating a different statement for every separately named variable. The values retain their individual positions.','Arrays organise related values under one indexed name.'],['Use the same operation on many values','A loop can change Index and process Marks[Index] repeatedly. The same instructions can read marks, calculate a total or search for a value. This is simpler to extend than writing a separate near-identical instruction for Mark1, Mark2 and so on.','Iteration can apply the same operation across an array.'],['Choose one or two dimensions','A 1D array suits a simple list; a 2D array suits related rows and columns, such as several students’ marks in several subjects. Declare suitable dimensions and bounds. Arrays provide structure, but do not automatically sort, validate or save the data permanently.','Choose dimensions to match a list or grid and perform needed processing explicitly.']],worked:['Store three marks and calculate their total.',['Group the data','Use one Marks array containing 4, 7 and 9.',[['Array name','Marks'],['Values','4, 7, 9']]],['Visit the positions','An index takes values 1, 2 and 3 to read each mark.',[['Index sequence','1 → 2 → 3'],['Selected values','4 → 7 → 9']]],['Reuse an update','For each position, add Marks[Index] to Total, giving 20.',[['Repeated statement','Total ← Total + Marks[Index]'],['Final total','20']]]],practice:[Q('Why is Marks[Index] useful when there are many marks?','The same statement can select each position as Index changes',['The same statement can select each position as Index changes','It makes every mark identical'],'A changing index lets one operation handle many elements.',[['Many values','One array'],['Changing Index','Select next position'],['Benefit','Reuse one statement']]),Q('Which arrangement suits a student-by-subject mark table?','2D array',['2D array','One Boolean value'],'Two indexes can select a student row and a subject column.',[['Dimension 1','Student'],['Dimension 2','Subject'],['Structure','2D array']])],assessment:[Q('Which is a main purpose of an array?','Organise related values for indexed access',['Organise related values for indexed access','Guarantee permanent storage','Encrypt every value'],'Arrays provide structured indexed storage during program use.'),Q('What usually combines with an array to process every element?','Iteration',['Iteration','Only a printer','Only a cookie'],'A loop visits its positions.'),Q('Which statement about arrays is correct?','They still need explicit processing, validation or saving when required',['They still need explicit processing, validation or saving when required','They automatically sort every input','They make all data non-volatile'],'An array does not perform unrelated tasks automatically.')],mistake:'Using an array does not save its values to a file automatically. That needs a separate file operation.',exam:'Explain array use for related collections and repeated processing, choosing suitable dimensions.',simple:'Keep a set of related values in numbered compartments, then use the same small job on each compartment.',another:'A daily-temperature array lets one loop find a total, maximum or minimum across all days.',helpFrames:[['Collection','Daily temperatures'],['Loop','Visit each index'],['Processing','Total / maximum / minimum']],terms:['array','iteration','variable','file']}),
C({id:'8.2.3',title:'Visit array cells with loops',minutes:15,opening:'An index can walk through a row. Two loop indexes can walk through a grid.',mission:'Read and write an array one iteration at a time.',sections:[['Read a 1D array in order','A FOR loop can set Index from the lower bound to the upper bound. Each iteration reads Values[Index]. Track both the index and selected value. If bounds are 1:4, use 1, 2, 3 and 4 exactly; 0 and 5 are outside this declaration.','A loop reads 1D elements using an index within the bounds.'],['Write through the index','INPUT Values[Index] stores input in the current position. An assignment such as Values[Index] ← Values[Index] * 2 replaces each visited value with its doubled value. Reading and writing are different actions even when they use the same indexed expression.','Assignments and input can write values into indexed array positions.'],['Use nested iteration for 2D','A row loop contains a column loop. For each row, the inner loop visits every valid column. Read or write Grid[Row,Column] at that position. The column loop restarts when the row changes. Follow the stated index order and bounds.','Nested loops visit 2D cells using row and column variables.']],worked:['Double every value in the 1D array 2, 4, 6.',['Visit index 1','Read 2 and replace it with 2 * 2 = 4.',[['Index','1'],['Array','4, 4, 6']]],['Visit index 2','Read the original second value 4 and replace it with 8.',[['Index','2'],['Array','4, 8, 6']]],['Visit index 3','Replace 6 with 12; the loop ends at its upper bound.',[['Index','3'],['Final array','4, 8, 12']]]],practice:[Q('A 2D array has 2 rows and 3 columns. How many cells does a full nested traversal visit?','6',['6','5','3'],'Each of two rows contains three visited columns.',[['Rows','2'],['Columns per row','3'],['Visits','2 × 3 = 6']]),Q('What does Values[Index] ← 0 do during an array loop?','Writes zero to the currently indexed cell',['Writes zero to the currently indexed cell','Changes the index bounds'],'The left-hand indexed expression identifies the cell to update.',[['Index','Current position'],['Assignment','Store 0'],['Changed','That cell']])],assessment:[Q('What changes on each ordinary FOR iteration through a 1D array?','The index used to select the current cell',['The index used to select the current cell','The array’s declared type','The number of dimensions always'],'The index walks through the declared positions.'),Q('Which expression selects a cell using two loop variables?','Grid[Row,Column]',['Grid[Row,Column]','Grid only with no position','Row[Grid] always'],'Two indexes select a 2D cell.'),Q('Why must loop limits match the array declaration?','To visit required cells without invalid indexes',['To visit required cells without invalid indexes','To guarantee every value equals zero','To avoid needing nested loops ever'],'Valid traversal stays within the declared bounds.')],mistake:'When a write changes an array cell, later reads see the new value. Trace updates in order.',exam:'Use iteration to read/write 1D arrays and nested iteration for 2D arrays, with variable indexes.',simple:'Move a pointer to one cell, do the job there, then move to the next. In a grid, finish the row before starting the next row.',another:'A 2 × 2 grid is visited at (1,1), (1,2), (2,1), (2,2). A write at one position leaves the other positions unchanged.',helpFrames:[['Row 1','(1,1) → (1,2)'],['Row 2','(2,1) → (2,2)'],['Write','Only the indexed cell']],terms:['array','iteration','variable','input','pseudocode']}),
C({id:'8.3.1',title:'Keep program data for the next run',minutes:10,opening:'A score held only in working memory disappears when the program ends. Save it in a file if it is needed later.',mission:'Compare temporary values with saved file data.',sections:[['Working values do not automatically last','Variables and arrays hold the data being used during execution. Their contents do not automatically become a retained record for another program run. If information must be kept, the program needs to write it to suitable storage.','Working variables and arrays need explicit saving for later runs.'],['A file keeps data for later use','A file is a named collection of data stored for later access. A program can write scores, settings or records to a file, then read them in a later run. The storage must retain the file; the program must know its name and data format.','Files keep program data for later access.'],['Load before processing again','Reading a file brings its stored data into the program’s working values. The program can then process it and write changes back when needed. Saving and reading are separate actions; editing a variable does not silently update its file unless the program performs that write.','Read saved data into working values and write changes when they must persist.']],worked:['Keep a high score of 12 between two runs.',['Working score','The current run holds HighScore = 12 in a variable.',[['During run','HighScore = 12'],['Storage','Working memory']]],['Write the file','Write 12 to a retained score file.',[['File','score.txt'],['Stored data','12']]],['Read next run','The next run reads the saved value and restores it into its working variable.',[['Next run','Read score.txt'],['Working HighScore','12']]]],practice:[Q('Does changing a variable automatically rewrite a saved file?','No',['No','Yes'],'A file changes only when the program performs an appropriate write.',[['Variable','Changed'],['File write','Not yet performed'],['Saved data','Still old value']]),Q('Why save settings in a file?','So a later run can read and reuse them',['So a later run can read and reuse them','To make every variable constant'],'A retained file can carry data between runs.',[['This run','Choose settings'],['Save file','Retain data'],['Next run','Read settings']])],assessment:[Q('What is a file’s role for program data?','Keep data for later use',['Keep data for later use','Execute every CPU command directly','Act as a sensor'],'Files provide retained named data.'),Q('What must a later run do to use the saved value?','Read the file into working data',['Read the file into working data','Assume every variable already contains it','Delete the file first'],'Saved data must be loaded before processing.'),Q('Which sequence preserves an updated score?','Update working value → write file → read in a later run',['Update working value → write file → read in a later run','Update variable only → assume it lasts forever','Close without writing → expect new data'],'An explicit write preserves the update.')],mistake:'The learning model’s file is simulated. Your lesson progress uses the site’s separate saved-progress system.',exam:'Explain why data is stored in files for later use by a program.',simple:'A note kept in a folder can be read tomorrow. A value remembered only during a task needs to be written down if it must last.',another:'Save a preferred volume level to a settings file, then read it when the program starts again.',helpFrames:[['Working setting','Volume = 6'],['Save','settings.txt'],['Next start','Read Volume = 6']],terms:['file','variable','array','secondary']}),
C({id:'8.3.2',title:'Open, read, write and close a file',minutes:16,opening:'Choose whether you need to read existing data or write new data, then open the file in the right mode.',mission:'Operate a simulated file with a visible read/write position.',sections:[['Open in the required mode','A program opens a file for reading or writing before using it. OPENFILE "scores.txt" FOR READ prepares existing data to be read. OPENFILE "scores.txt" FOR WRITE prepares writing; in this model it replaces previous contents. The mode limits the operations allowed.','Open a file in a suitable read or write mode before using it.'],['Read or write items and lines','READFILE reads an item into a variable; WRITEFILE writes a value. A line of text can also be read or written as a string. Repeated reads advance through the stored data. A program must avoid reading beyond the end of the file. The model shows items stored within text lines.','Read/write operations transfer individual items or lines between a file and program values.'],['Close when finished','CLOSEFILE releases the file and finishes the program’s use of it. Writing changes should be completed and the file properly closed. Later, reopen for reading to check the stored result. A real file system can report errors such as a missing file; the model makes its operations and limits explicit.','Close a file after use and reopen in the needed mode for later access.']],worked:['Write the text line "Hello", close the file, then read it.',['Open and write','Open the example file FOR WRITE and write the text line.',[['Mode','WRITE'],['Data','Hello']]],['Close','Close the file after the write.',[['Action','CLOSEFILE'],['Stored line','Hello']]],['Reopen and read','Open FOR READ and read the first line into a string variable.',[['Mode','READ'],['Variable value','Hello']]]],practice:[Q('A file is open FOR READ. Is writing allowed in that mode?','No',['No','Yes'],'Read mode is for reading existing data, not writing.',[['Open mode','READ'],['Requested action','WRITE'],['Result','Wrong mode']]),Q('What should happen when the program finishes using a file?','Close it',['Close it','Read past its end forever'],'Closing finishes the file operation and releases its use.',[['Work','Finished'],['File','Still open'],['Action','CLOSEFILE']])],assessment:[Q('Which operation prepares an existing file for reading?','OPENFILE ... FOR READ',['OPENFILE ... FOR READ','CLOSEFILE only','OUTPUT a filename only'],'The file must be opened in read mode.'),Q('What happens to the read position after reading the next stored item?','It advances towards the following item',['It advances towards the following item','It must always return to the first item','It erases every line'],'Repeated reads move through the stored data.'),Q('Why should a program check for the end of file?','To avoid attempting to read data that is not there',['To avoid attempting to read data that is not there','To turn text into machine code','To make all writes permanent without closing'],'End-of-file handling prevents invalid reads.')],mistake:'Opening FOR WRITE can replace old contents. Do not choose it when you only intend to read the existing file.',exam:'Open, close, read and write files, including single data items and lines of text, using the correct mode.',simple:'Open the right folder for the job, take or place data one piece at a time, then close it when finished.',another:'A program opens a file FOR READ, reads a stored mark into Mark, uses it, then closes the file.',helpFrames:[['Open','FOR READ'],['Read','File item → Mark'],['Finish','CLOSEFILE']],terms:['file','string','variable','pseudocode']})
];
